reference_solution:
def edit_distance(left, right):
    previous = list(range(len(right) + 1))
    for i, a in enumerate(left, 1):
        current = [i]
        for j, b in enumerate(right, 1):
            current.append(previous[j - 1] if a == b else 1 + min(previous[j], current[-1], previous[j - 1]))
        previous = current
    return previous[-1]

